package at.heinz.deviceai.learning.span

import java.io.File
import java.util.Locale
import java.util.Random
import kotlin.math.exp
import kotlin.math.ln
import org.json.JSONArray
import org.json.JSONObject

/**
 * RESEARCH_SHADOW. An 11-parameter log-linear attention distribution over copied UTF-16
 * spans plus NOANSWER, optimized by supervised classifier NLL. No generated bytes.
 * Handwritten German static-location grammar provides entity/relation/full-span/risk
 * features. This is substantial task-specific prior knowledge, not learned language parsing.
 * Runtime features receive only question + evidence; labels exist only in training/evaluation.
 * Independent existing verifier and rule baseline run AFTER the raw argmax is fixed.
 */
object Cdx2PointerCandidate {
    const val SCHEMA = "CDX2_POINTER_LOG_LINEAR_V1"
    val featureNames = listOf("spanBias", "entityPrefix", "relationPrefix", "entityRelationPrefix",
        "wholeStaticLocation", "spanRisk", "spanAmbiguity", "noAnswerBias", "noBinding",
        "noAnswerRisk", "unsupportedQuestion")
    data class Example(val id: String, val question: String,
        val sources: List<EvidenceBoundNaturalLocationProbe.Evidence>,
        val expected: EvidenceBoundNaturalLocationProbe.Decision.Found?)
    data class Option(val found: EvidenceBoundNaturalLocationProbe.Decision.Found?, val features: DoubleArray)
    private val query = Regex("""(?iu)^\s*wo\s+(ist|wohnt|lebt|steht)\s+([\p{L}][\p{L}\p{M}-]{1,31})\s*\?\s*$""")
    private val word = Regex("""[\p{Lu}][\p{L}\p{M}-]{1,40}""")
    private val assertion = Regex("""(?iu)^\s*([\p{L}][\p{L}\p{M}-]{1,31})\s+(ist|wohnt|lebt|steht)\s+in\s+(.+?)\s*$""")
    private val location = Regex("""[\p{Lu}][\p{L}\p{M}-]{1,40}(?:\s+[\p{Lu}][\p{L}\p{M}-]{1,40}){0,2}""")
    private val split = Regex("""[.!?;,]|\s+und\s+(?=[\p{L}][\p{L}\p{M}-]{1,31}\s+(?:ist|wohnt|lebt|steht)\s+in\s)""", RegexOption.IGNORE_CASE)
    private val risk = Regex("""(?iu)\b(?:nicht|kein|keine|sondern|stattdessen|gestern|heute|morgen|früher|damals|aktuell|seit|vorher|später|sie|er|es|das|dies|diese|dieser|dieses|jene|jener|korrektur|widerruf|widerrufen|falsch|nein|ungültig)\b|["„“”«»]""")
    fun valid(question: String, sources: List<EvidenceBoundNaturalLocationProbe.Evidence>): Boolean =
        question.length <= 160 && question.none(Char::isISOControl) && sources.size in 1..4 &&
        sources.sumOf { it.text.length.toLong() } <= 4096 && sources.map { it.sourceId }.distinct().size == sources.size &&
        sources.all { it.revision > 0 && it.sourceId.matches(Regex("[a-zA-Z0-9._:-]{1,96}")) &&
            it.sha256.matches(Regex("[0-9a-f]{64}")) && it.text.isNotBlank() && it.text.none(Char::isISOControl) &&
            Charsets.UTF_8.newEncoder().canEncode(it.text) && EvidenceBoundNaturalLocationProbe.digest(it.text) == it.sha256 }

    /** Positional candidates include every 1..3 adjacent capitalized word sequence, not gold spans. */
    fun options(question: String, sources: List<EvidenceBoundNaturalLocationProbe.Evidence>): List<Option> {
        if (!valid(question, sources)) return listOf(Option(null, DoubleArray(11).also { it[7] = 1.0 }))
        val q = query.matchEntire(question)
        val subject = q?.groupValues?.get(2)
        val relation = q?.groupValues?.get(1)?.lowercase(Locale.ROOT)
        data class Clause(val source: EvidenceBoundNaturalLocationProbe.Evidence, val start: Int, val text: String)
        val clauses = sources.flatMap { source ->
            val result = mutableListOf<Clause>(); var start = 0
            for (s in split.findAll(source.text)) {
                result += Clause(source, start, source.text.substring(start, s.range.first)); start = s.range.last + 1
            }
            result += Clause(source, start, source.text.substring(start)); result
        }
        val mention = subject?.let { Regex("""(?iu)(?<![\p{L}\p{M}\p{N}-])""" + Regex.escape(it) + """(?![\p{L}\p{M}\p{N}-])""") }
        // Risk is question/evidence syntax only. The verifier is never called by options/raw.
        val risky = sources.any { risk.containsMatchIn(it.text) } || clauses.any {
            val m = assertion.matchEntire(it.text)
            mention?.containsMatchIn(it.text) == true && (m == null || !location.matches(m.groupValues[3]) ||
                sourceQuestionTerminator(it.source.text, it.start + it.text.length))
        }
        val bindingCount = clauses.count { c -> assertion.matchEntire(c.text)?.let { m ->
            m.groupValues[1].equals(subject, true) && m.groupValues[2].equals(relation, true)
        } == true }
        val out = mutableListOf<Option>()
        out += Option(null, DoubleArray(11).also {
            it[7] = 1.0; it[8] = if (bindingCount == 0) 1.0 else 0.0
            it[9] = if (risky || bindingCount > 1) 1.0 else 0.0; it[10] = if (q == null) 1.0 else 0.0
        })
        for (c in clauses) {
            val parsed = assertion.matchEntire(c.text)
            val entityMatch = parsed?.groupValues?.get(1)?.equals(subject, true) == true
            val relationMatch = parsed?.groupValues?.get(2)?.equals(relation, true) == true
            val target = parsed?.groups?.get(3)
            val tokens = word.findAll(c.text).toList()
            for (i in tokens.indices) for (n in 1..3) {
                if (i + n > tokens.size) continue
                val first = tokens[i].range.first; val end = tokens[i+n-1].range.last + 1
                val text = c.text.substring(first, end)
                if (!location.matches(text)) continue
                val withinTarget = target != null && first >= target.range.first && end <= target.range.last + 1
                val whole = target != null && first == target.range.first && end == target.range.last + 1
                val f = DoubleArray(11)
                f[0] = 1.0; f[1] = if (withinTarget && entityMatch) 1.0 else 0.0
                f[2] = if (withinTarget && relationMatch) 1.0 else 0.0
                f[3] = f[1] * f[2]; f[4] = if (whole) 1.0 else 0.0
                f[5] = if (risky) 1.0 else 0.0; f[6] = if (bindingCount > 1) 1.0 else 0.0
                out += Option(EvidenceBoundNaturalLocationProbe.Decision.Found(text, c.source.sourceId,
                    c.source.revision, c.source.sha256, c.start+first, c.start+end), f)
            }
        }
        return out
    }
    private fun sourceQuestionTerminator(text: String, end: Int) = end < text.length && text[end] == '?'
    fun probabilities(weights: DoubleArray, options: List<Option>): DoubleArray {
        require(weights.size == 11 && weights.all { it.isFinite() && kotlin.math.abs(it) <= 100.0 }) {
            "isolated checkpoint requires 11 finite weights with absolute value <= 100"
        }
        val scores = options.map { o -> weights.indices.sumOf { weights[it] * o.features[it] } }
        val max = scores.max(); val exps = scores.map { exp(it-max) }; val sum = exps.sum()
        return DoubleArray(exps.size) { exps[it] / sum }
    }
    fun raw(weights: DoubleArray, question: String, sources: List<EvidenceBoundNaturalLocationProbe.Evidence>): EvidenceBoundNaturalLocationProbe.Decision.Found? {
        val os = options(question, sources); val ps = probabilities(weights, os)
        return os[ps.indices.maxBy { ps[it] }].found // deterministic ties choose NOANSWER first
    }
    private fun target(os: List<Option>, expected: EvidenceBoundNaturalLocationProbe.Decision.Found?): Int =
        os.indexOfFirst { it.found == expected }.also { require(it >= 0) { "Gold tuple absent from candidate set" } }
    fun lossGradient(weights: DoubleArray, os: List<Option>, expected: EvidenceBoundNaturalLocationProbe.Decision.Found?): Pair<Double, DoubleArray> {
        val label = target(os, expected); val ps = probabilities(weights, os)
        return -ln(ps[label].coerceAtLeast(1e-300)) to DoubleArray(11) { k ->
            os.indices.sumOf { ps[it] * os[it].features[k] } - os[label].features[k]
        }
    }
    fun nll(weights: DoubleArray, examples: List<Example>) = examples.map {
        lossGradient(weights, options(it.question, it.sources), it.expected).first
    }.average()
    fun train(examples: List<Example>, epochs: Int, rate: Double): DoubleArray {
        require(examples.size in 1..512 && epochs in 1..100 && rate in 0.001..0.5)
        val data = examples.map { options(it.question, it.sources) to it.expected }
        val weights = DoubleArray(11); val order = data.indices.toMutableList(); val rng = Random(17)
        repeat(epochs) {
            java.util.Collections.shuffle(order, rng)
            for (i in order) {
                val grad = lossGradient(weights, data[i].first, data[i].second).second
                for (k in weights.indices) weights[k] -= rate * grad[k]
            }
        }
        return weights
    }
    fun tuple(found: EvidenceBoundNaturalLocationProbe.Decision.Found?): JSONObject = if (found == null)
        JSONObject().put("decision", "NOANSWER") else JSONObject().put("decision", "SPAN").put("text", found.text)
            .put("sourceId", found.sourceId).put("revision", found.revision).put("sha256", found.sha256)
            .put("start", found.start).put("endExclusive", found.endExclusive).put("offsetEncoding", "UTF-16")
    fun verified(question: String, sources: List<EvidenceBoundNaturalLocationProbe.Evidence>, found: EvidenceBoundNaturalLocationProbe.Decision.Found?) =
        found != null && valid(question, sources) && sources.singleOrNull { it.sourceId == found.sourceId }?.let {
            it.revision == found.revision && it.sha256 == found.sha256 && found.start >= 0 &&
                found.endExclusive <= it.text.length && found.endExclusive > found.start &&
                it.text.substring(found.start, found.endExclusive) == found.text
        } == true && EvidenceBoundNaturalLocationVerifier.verify(question, sources, found)
    fun sources(json: JSONArray) = (0 until json.length()).map { i -> json.getJSONObject(i).let {
        val revision=it.get("revision")
        require(revision is Int || revision is Long) { "revision must be an exact integer" }
        val rev=(revision as Number).toLong();require(rev in Int.MIN_VALUE.toLong()..Int.MAX_VALUE.toLong())
        EvidenceBoundNaturalLocationProbe.Evidence(it.getString("sourceId"), rev.toInt(),
            it.getString("sha256"), it.getString("text")) } }
    fun example(json: JSONObject): Example {
        val ss = sources(json.getJSONArray("sources")); val e = json.optJSONObject("expected")
        val found = if (e == null || e.optString("decision") == "NOANSWER") null else
            EvidenceBoundNaturalLocationProbe.Decision.Found(e.getString("text"), e.getString("sourceId"),
                e.getInt("revision"), e.getString("sha256"), e.getInt("start"), e.getInt("endExclusive"))
        return Example(json.getString("id"), json.getString("question"), ss, found)
    }
    fun readExamples(path: String): List<Example> {
        val a = JSONObject(File(path).readText()).getJSONArray("cases")
        return (0 until a.length()).map { example(a.getJSONObject(it)) }
    }
    fun checkpoint(weights: DoubleArray, epochs: Int, rate: Double, trainHash: String, devHash: String) =
        JSONObject().put("schema", SCHEMA).put("featureNames", JSONArray(featureNames)).put("weights", JSONArray(weights.toList()))
            .put("seed", 17).put("epochs", epochs).put("rate", rate).put("trainSha256", trainHash).put("devSha256", devHash)
            .put("objective", "span/noanswer classifier NLL; not generative byte NLL").put("promotion", "FORBIDDEN_RESEARCH_ONLY")
    fun load(path: String): DoubleArray {
        val j = JSONObject(File(path).readText()); require(j.getString("schema") == SCHEMA)
        require(j.getJSONArray("featureNames").toString() == JSONArray(featureNames).toString())
        val a = j.getJSONArray("weights"); require(a.length() == 11)
        return DoubleArray(11) { a.getDouble(it) }.also { require(it.all { w -> w.isFinite() && kotlin.math.abs(w)<=100.0 }) }
    }
    @JvmStatic fun main(args: Array<String>) {
        require(args.isNotEmpty()) { "train TRAIN.json DEV.json CHECKPOINT.json REPORT.json | predict CHECKPOINT.json REQUEST.json OUTPUT.json" }
        if (args[0] == "train") {
            require(args.size == 5); require(!File(args[3]).exists() && !File(args[4]).exists())
            val train = readExamples(args[1]); val dev = readExamples(args[2]); val start = System.nanoTime()
            val cpu=java.lang.management.ManagementFactory.getThreadMXBean();val cpuStart=cpu.currentThreadCpuTime
            var best: DoubleArray? = null; var bestLoss = Double.POSITIVE_INFINITY; var epochs = 0; var rate = 0.0
            val trials = JSONArray()
            for (ep in listOf(20, 60)) for (lr in listOf(.05, .15)) {
                val w = train(train, ep, lr); val loss = nll(w, dev)
                trials.put(JSONObject().put("epochs",ep).put("rate",lr).put("devClassifierNll",loss))
                if (loss < bestLoss) { best = w; bestLoss = loss; epochs = ep; rate = lr }
            }
            val w = best!!; val millis = (System.nanoTime()-start)/1_000_000.0
            File(args[3]).writeText(checkpoint(w, epochs, rate, EvidenceBoundNaturalLocationProbe.digest(File(args[1]).readText()),
                EvidenceBoundNaturalLocationProbe.digest(File(args[2]).readText())).toString(2)+"\n")
            File(args[4]).writeText(JSONObject().put("schema",SCHEMA).put("parameterCount",11).put("trainItems",train.size)
                .put("devItems",dev.size).put("trainNllBefore",nll(DoubleArray(11),train)).put("trainNllAfter",nll(w,train))
                .put("devClassifierNll",bestLoss).put("trials",trials).put("trainMillis",millis)
                .put("trainCurrentThreadCpuMillis",(cpu.currentThreadCpuTime-cpuStart)/1_000_000.0)
                .put("checkpointBytes",File(args[3]).length()).put("selection","DEV NLL only").toString(2)+"\n")
        } else {
            require(args[0] == "predict" && args.size == 4); require(!File(args[3]).exists())
            val w = load(args[1]); val request = JSONObject(File(args[2]).readText())
            val ss = sources(request.getJSONArray("sources")); val question = request.getString("question")
            val start = System.nanoTime(); val found = raw(w, question, ss); val ms = (System.nanoTime()-start)/1_000_000.0
            val pass = verified(question, ss, found)
            val rule = EvidenceBoundNaturalLocationProbe.answer(question, ss) as? EvidenceBoundNaturalLocationProbe.Decision.Found
            File(args[3]).writeText(JSONObject().put("schema",SCHEMA).put("RAW",tuple(found)).put("VERIFIED",tuple(if(pass)found else null))
                .put("verifierAccepted",pass).put("RULE",tuple(rule)).put("rawMillis",ms).put("parameterCount",11)
                .put("checkpointBytes",File(args[1]).length()).put("classificationOnly",true).toString(2)+"\n")
        }
    }
}
